@Test(description = "Unit test for simple cache refresh")
public void testSimpleCacheRefresh() {
    PropertyCache.PropertyCacheKeyFuncs propertyCacheKeyFuncs = mock(PropertyCache.PropertyCacheKeyFuncs.class);
    // Return a random property key, it does not impact test result.
    when(propertyCacheKeyFuncs.getRootKey(any(HelixDataAccessor.class))).thenReturn(new PropertyKey(IDEALSTATES, IdealState.class, "Foobar"));
    PropertyCache<HelixProperty> propertyCache = new PropertyCache<>(MOCK_CONTROL_CONTEXT_PROVIDER, "mock property cache", propertyCacheKeyFuncs, false);
    HelixDataAccessor accessor = mock(HelixDataAccessor.class);
    Map<String, HelixProperty> propertyConfigMap = ImmutableMap.of("id", new HelixProperty("test"));
    when(accessor.getChildValuesMap(any(PropertyKey.class), anyBoolean())).thenReturn(propertyConfigMap);
    propertyCache.refresh(accessor);
    Assert.assertEquals(propertyCache.getPropertyMap(), propertyConfigMap);
    Assert.assertEquals(propertyCache.getPropertyByName("id"), new HelixProperty("test"));
}

