    String instanceNameA = INSTANCE + "A";
    String instanceNameB = INSTANCE + "B";
    String instanceNameC = INSTANCE + "C";
    AssignableNode testAssignableNode = mock(AssignableNode.class);
    ResourceAssignment bestPossibleResourceAssignment = mock(ResourceAssignment.class);
    when(bestPossibleResourceAssignment.getReplicaMap(new Partition(PARTITION))).thenReturn(ImmutableMap.of(instanceNameA, "Master", instanceNameB, "Slave"));
    when(_clusterContext.getBestPossibleAssignment()).thenReturn(ImmutableMap.of(RESOURCE, bestPossibleResourceAssignment));
    ResourceAssignment baselineResourceAssignment = mock(ResourceAssignment.class);
    when(baselineResourceAssignment.getReplicaMap(new Partition(PARTITION))).thenReturn(ImmutableMap.of(instanceNameA, "Slave", instanceNameC, "Master"));
    when(_clusterContext.getBaselineAssignment()).thenReturn(ImmutableMap.of(RESOURCE, baselineResourceAssignment));
    // when the replica's state matches with best possible, allocation matches with baseline
    when(testAssignableNode.getInstanceName()).thenReturn(instanceNameA);
    when(testAssignableNode.getLogicalId()).thenReturn(instanceNameA);
    when(_testReplica.getReplicaState()).thenReturn("Master");
    verifyScore(_baselineInfluenceConstraint, testAssignableNode, _testReplica, _clusterContext, 0.5, 0.5);
    verifyScore(_partitionMovementConstraint, testAssignableNode, _testReplica, _clusterContext, 1.0, 1.0);
    // when the replica's allocation matches with best possible only
    when(testAssignableNode.getInstanceName()).thenReturn(instanceNameB);
    when(testAssignableNode.getLogicalId()).thenReturn(instanceNameB);
    when(_testReplica.getReplicaState()).thenReturn("Master");
    verifyScore(_baselineInfluenceConstraint, testAssignableNode, _testReplica, _clusterContext, 0.0, 0.0);
    verifyScore(_partitionMovementConstraint, testAssignableNode, _testReplica, _clusterContext, 0.5, 0.5);
    // when the replica's state matches with baseline only
    when(testAssignableNode.getInstanceName()).thenReturn(instanceNameC);
    when(testAssignableNode.getLogicalId()).thenReturn(instanceNameC);
    when(_testReplica.getReplicaState()).thenReturn("Master");
    verifyScore(_baselineInfluenceConstraint, testAssignableNode, _testReplica, _clusterContext, 1.0, 1.0);
    verifyScore(_partitionMovementConstraint, testAssignableNode, _testReplica, _clusterContext, 0.0, 0.0);
    // when the replica's allocation matches with baseline only
    when(testAssignableNode.getInstanceName()).thenReturn(instanceNameC);
    when(testAssignableNode.getLogicalId()).thenReturn(instanceNameC);
    when(_testReplica.getReplicaState()).thenReturn("Slave");
    verifyScore(_baselineInfluenceConstraint, testAssignableNode, _testReplica, _clusterContext, 0.5, 0.5);
    verifyScore(_partitionMovementConstraint, testAssignableNode, _testReplica, _clusterContext, 0.0, 0.0);
}

