@Test
public void testFindToBeAssignedReplicasForMinActiveReplica() throws IOException {
    ResourceControllerDataProvider testCache = setupClusterDataCache();
    String instance1 = _testInstanceId;
    String offlineInstance = _testInstanceId + "1";
    String instance2 = _testInstanceId + "2";
    Map<String, LiveInstance> liveInstanceMap = new HashMap<>();
    liveInstanceMap.put(instance1, createMockLiveInstance(instance1));
    liveInstanceMap.put(instance2, createMockLiveInstance(instance2));
    Set<String> activeInstances = new HashSet<>();
    activeInstances.add(instance1);
    activeInstances.add(instance2);
    when(testCache.getAssignableLiveInstances()).thenReturn(liveInstanceMap);
    when(testCache.getEnabledLiveInstances()).thenReturn(activeInstances);
    // test 0, empty input
    Assert.assertEquals(DelayedRebalanceUtil.findToBeAssignedReplicasForMinActiveReplica(testCache, Collections.emptySet(), activeInstances, Collections.emptyMap(), new HashMap<>()), Collections.emptySet());
    // test 1, one partition under minActiveReplica
    Map<String, Map<String, Map<String, String>>> input = ImmutableMap.of(_resourceNames.get(0), ImmutableMap.of(_partitionNames.get(0), ImmutableMap.of("MASTER", instance1), _partitionNames.get(1), // Partition2-MASTER
    ImmutableMap.of("OFFLINE", offlineInstance)), _resourceNames.get(1), ImmutableMap.of(_partitionNames.get(2), ImmutableMap.of("MASTER", instance1), _partitionNames.get(3), ImmutableMap.of("SLAVE", instance1)));
    // to populate
    Map<String, Set<AssignableReplica>> replicaMap = new HashMap<>();
    // to populate
    Map<String, ResourceAssignment> currentAssignment = new HashMap<>();
    prepareData(input, replicaMap, currentAssignment, testCache, 1);
    Map<String, Set<AssignableReplica>> allocatedReplicas = new HashMap<>();
    Set<AssignableReplica> toBeAssignedReplicas = DelayedRebalanceUtil.findToBeAssignedReplicasForMinActiveReplica(testCache, replicaMap.keySet(), activeInstances, currentAssignment, allocatedReplicas);
    Assert.assertEquals(toBeAssignedReplicas.size(), 1);
    Assert.assertTrue(toBeAssignedReplicas.stream().map(AssignableReplica::toString).collect(Collectors.toSet()).contains("Resource1-Partition2-MASTER"));
    AssignableReplica replica = toBeAssignedReplicas.iterator().next();
    Assert.assertEquals(replica.getReplicaState(), "MASTER");
    Assert.assertEquals(replica.getPartitionName(), "Partition2");
    // test 2, no additional replica to be assigned
    testCache = setupClusterDataCache();
    when(testCache.getAssignableLiveInstances()).thenReturn(liveInstanceMap);
    when(testCache.getEnabledLiveInstances()).thenReturn(activeInstances);
    input = ImmutableMap.of(_resourceNames.get(0), ImmutableMap.of(_partitionNames.get(0), ImmutableMap.of("MASTER", instance1), _partitionNames.get(1), ImmutableMap.of("SLAVE", instance2)), _resourceNames.get(1), ImmutableMap.of(_partitionNames.get(2), ImmutableMap.of("MASTER", instance1), _partitionNames.get(3), ImmutableMap.of("SLAVE", instance2)));
    // to populate
    replicaMap = new HashMap<>();
