    when(clusterData.getInstanceOfflineTimeMap()).thenReturn(instanceOfflineTimeMap);
    Map<String, InstanceConfig> instanceConfigMap = clusterData.getAssignableInstanceConfigMap();
    instanceConfigMap.put(offlineInstance, createMockInstanceConfig(offlineInstance));
    when(clusterData.getAssignableInstanceConfigMap()).thenReturn(instanceConfigMap);
    when(clusterData.getInstanceConfigMap()).thenReturn(instanceConfigMap);
    // Set minActiveReplica to 0 so that requireRebalanceOverwrite returns false
    Map<String, IdealState> isMap = new HashMap<>();
    for (String resource : _resourceNames) {
        IdealState idealState = clusterData.getIdealState(resource);
        idealState.setMinActiveReplicas(0);
        isMap.put(resource, idealState);
    }
    when(clusterData.getIdealState(anyString())).thenAnswer((Answer<IdealState>) invocationOnMock -> isMap.get(invocationOnMock.getArguments()[0]));
    when(clusterData.getIdealStates()).thenReturn(isMap);
    MockRebalanceAlgorithm spyAlgorithm = Mockito.spy(new MockRebalanceAlgorithm());
    WagedRebalancer rebalancer = Mockito.spy(new WagedRebalancer(_metadataStore, spyAlgorithm, Optional.empty()));
    // Cluster config change will trigger baseline to be recalculated.
    when(clusterData.getRefreshedChangeTypes()).thenReturn(Collections.singleton(HelixConstants.ChangeType.CLUSTER_CONFIG));
    Map<String, Resource> resourceMap = clusterData.getIdealStates().entrySet().stream().collect(Collectors.toMap(Map.Entry::getKey, entry -> {
        Resource resource = new Resource(entry.getKey());
        entry.getValue().getPartitionSet().forEach(resource::addPartition);
        return resource;
    }));
    // Populate best possible assignment
    rebalancer.computeNewIdealStates(clusterData, resourceMap, new CurrentStateOutput());
    verify(rebalancer, times(1)).requireRebalanceOverwrite(any(), any());
    Assert.assertEquals(rebalancer.getMetricCollector().getMetric(WagedRebalancerMetricCollector.WagedRebalancerMetricNames.RebalanceOverwriteCounter.name(), CountMetric.class).getValue().longValue(), 0L);
    Assert.assertEquals(rebalancer.getMetricCollector().getMetric(WagedRebalancerMetricCollector.WagedRebalancerMetricNames.RebalanceOverwriteLatencyGauge.name(), LatencyMetric.class).getLastEmittedMetricValue().longValue(), -1L);
    // Set minActiveReplica to 1 so that requireRebalanceOverwrite returns true
    for (String resource : _resourceNames) {
        IdealState idealState = clusterData.getIdealState(resource);
        idealState.setMinActiveReplicas(3);
        isMap.put(resource, idealState);
    }
    when(clusterData.getIdealState(anyString())).thenAnswer((Answer<IdealState>) invocationOnMock -> isMap.get(invocationOnMock.getArguments()[0]));
    when(clusterData.getIdealStates()).thenReturn(isMap);
    _metadataStore.reset();
    // Update the config so the cluster config will be marked as changed.
    clusterConfig = clusterData.getClusterConfig();
    Map<String, Integer> defaultCapacityMap = new HashMap<>(clusterConfig.getDefaultInstanceCapacityMap());
    defaultCapacityMap.put("foobar", 0);
    clusterConfig.setDefaultInstanceCapacityMap(defaultCapacityMap);
    clusterData.setClusterConfig(clusterConfig);
    rebalancer.computeNewIdealStates(clusterData, resourceMap, new CurrentStateOutput());
    verify(rebalancer, times(2)).requireRebalanceOverwrite(any(), any());
    Assert.assertEquals(rebalancer.getMetricCollector().getMetric(WagedRebalancerMetricCollector.WagedRebalancerMetricNames.RebalanceOverwriteCounter.name(), CountMetric.class).getValue().longValue(), 1L);
    Assert.assertTrue(rebalancer.getMetricCollector().getMetric(WagedRebalancerMetricCollector.WagedRebalancerMetricNames.RebalanceOverwriteLatencyGauge.name(), LatencyMetric.class).getLastEmittedMetricValue() > 0L);
}

