@Test
public void testSkipCapacityCalculation() {
    // case: when resource-map is null
    Assert.assertTrue(CurrentStateComputationStage.skipCapacityCalculation(new ResourceControllerDataProvider(), null, new ClusterEvent(ClusterEventType.LiveInstanceChange)));
    // case: when resource-map is empty
    Assert.assertTrue(CurrentStateComputationStage.skipCapacityCalculation(new ResourceControllerDataProvider(), ImmutableMap.of(), new ClusterEvent(ClusterEventType.LiveInstanceChange)));
    // case: when instance capacity is null
    Assert.assertFalse(CurrentStateComputationStage.skipCapacityCalculation(new ResourceControllerDataProvider(), _resourceMap, new ClusterEvent(ClusterEventType.LiveInstanceChange)));
    // case: when event is of no-op
    ResourceControllerDataProvider dataProvider = Mockito.mock(ResourceControllerDataProvider.class);
    WagedInstanceCapacity instanceCapacity = Mockito.mock(WagedInstanceCapacity.class);
    Mockito.when(dataProvider.getWagedInstanceCapacity()).thenReturn(instanceCapacity);
    Assert.assertTrue(CurrentStateComputationStage.skipCapacityCalculation(dataProvider, _resourceMap, new ClusterEvent(ClusterEventType.CustomizedStateChange)));
    Assert.assertTrue(CurrentStateComputationStage.skipCapacityCalculation(dataProvider, _resourceMap, new ClusterEvent(ClusterEventType.CustomizedViewChange)));
    Assert.assertTrue(CurrentStateComputationStage.skipCapacityCalculation(dataProvider, _resourceMap, new ClusterEvent(ClusterEventType.CustomizeStateConfigChange)));
    Assert.assertTrue(CurrentStateComputationStage.skipCapacityCalculation(dataProvider, _resourceMap, new ClusterEvent(ClusterEventType.ExternalViewChange)));
    Assert.assertTrue(CurrentStateComputationStage.skipCapacityCalculation(dataProvider, _resourceMap, new ClusterEvent(ClusterEventType.IdealStateChange)));
    Assert.assertTrue(CurrentStateComputationStage.skipCapacityCalculation(dataProvider, _resourceMap, new ClusterEvent(ClusterEventType.OnDemandRebalance)));
    Assert.assertTrue(CurrentStateComputationStage.skipCapacityCalculation(dataProvider, _resourceMap, new ClusterEvent(ClusterEventType.Resume)));
    Assert.assertTrue(CurrentStateComputationStage.skipCapacityCalculation(dataProvider, _resourceMap, new ClusterEvent(ClusterEventType.RetryRebalance)));
    Assert.assertTrue(CurrentStateComputationStage.skipCapacityCalculation(dataProvider, _resourceMap, new ClusterEvent(ClusterEventType.StateVerifier)));
    Assert.assertTrue(CurrentStateComputationStage.skipCapacityCalculation(dataProvider, _resourceMap, new ClusterEvent(ClusterEventType.TargetExternalViewChange)));
    Assert.assertTrue(CurrentStateComputationStage.skipCapacityCalculation(dataProvider, _resourceMap, new ClusterEvent(ClusterEventType.TaskCurrentStateChange)));
    Assert.assertFalse(CurrentStateComputationStage.skipCapacityCalculation(dataProvider, _resourceMap, new ClusterEvent(ClusterEventType.LiveInstanceChange)));
    Assert.assertFalse(CurrentStateComputationStage.skipCapacityCalculation(dataProvider, _resourceMap, new ClusterEvent(ClusterEventType.CurrentStateChange)));
    Assert.assertFalse(CurrentStateComputationStage.skipCapacityCalculation(dataProvider, _resourceMap, new ClusterEvent(ClusterEventType.MessageChange)));
    Assert.assertFalse(CurrentStateComputationStage.skipCapacityCalculation(dataProvider, _resourceMap, new ClusterEvent(ClusterEventType.PeriodicalRebalance)));
}

